INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q56','exam-fe','サービス可用性','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問56・改編】サービス提供時間は7時から19時までで、7時に予定どおり開始した。16時に障害で停止し、21時まで修理を続け当日は再開しなかった。計画停止がない場合、当日の可用性は何％か（小数点以下切捨て）。','[{"id":"a","text":"25"},{"id":"b","text":"60"},{"id":"c","text":"64"},{"id":"d","text":"75"}]','"d"','提供予定は12時間、そのうち7時から16時までの9時間が稼働した。9÷12×100＝75％。サービス提供時間外の19時以降は分母に含めない。 中文解析：计划服务12小时，实际运行9小时，所以可用性为75%；19时以后的修理时间不计入计划服务时间。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q57','exam-fe','インシデント','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問57・改編】夜間バッチで注文書出力プログラムが異常終了し、担当者が検知、保守担当者が緊急出社して復旧し、後日プログラムの誤りを修正した。インシデントに該当するものはどれか。','[{"id":"a","text":"異常終了の検知"},{"id":"b","text":"プログラムの誤り"},{"id":"c","text":"プログラムの異常終了"},{"id":"d","text":"保守担当者の緊急出社"}]','"c"','インシデントはサービスの中断や品質低下を引き起こす事象である。この例ではプログラムの異常終了が該当する。プログラムの誤りは原因である。 中文解析：事件是导致服务中断或质量下降的情况，本题为程序异常结束；程序错误是原因。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q58','exam-fe','システム監査の独立性','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問58・改編】情報システム部が開発し経理部が運用する会計システムを監査する。監査人の所属に関する最も適切な扱いはどれか。','[{"id":"a","text":"会計に関するシステムなので必ず公認会計士とする"},{"id":"b","text":"機密情報を扱うので経理部長直属とする"},{"id":"c","text":"効率のため情報システム部長直属とする"},{"id":"d","text":"独立性を確保するため情報システム部にも経理部にも所属しない者とする"}]','"d"','監査対象の開発・運用から独立した立場で監査し、客観性を確保する。 中文解析：审计人员应独立于被审计系统的开发和运营部门，以保证客观性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q59','exam-fe','システム監査報告','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問59・改編】システム監査報告書に記載する指摘事項の説明として適切なものはどれか。','[{"id":"a","text":"証拠の有無を問わず監査人が必要と判断した事項を記載する"},{"id":"b","text":"監査人が必要と判断した事項のうち対象部門の責任者が承認したものだけを記載する"},{"id":"c","text":"調査結果に事実誤認がないことを対象部門に確認し、監査人が必要と判断した事項を記載する"},{"id":"d","text":"重要性にかかわらず全ての不備を漏れなく記載する"}]','"c"','事実関係に誤認がないことを対象部門に確認したうえで、監査人が独立した判断により必要な指摘を記載する。 中文解析：应向被审计部门确认事实无误，再由审计人员独立判断需要报告的问题。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q61','exam-fe','RPA','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問61・改編】人手不足の解消を目的とした業務革新におけるRPAの活用例はどれか。','[{"id":"a","text":"入力や照合など標準化された定型事務をソフトウェアで自動処理する"},{"id":"b","text":"製造ラインの組立作業員を産業用ロボットに置き換える"},{"id":"c","text":"接客販売を画像解析と電子決済を備えた無人店舗に置き換える"},{"id":"d","text":"フォークリフトによる入出庫を無人倉庫に置き換える"}]','"a"','RPAはソフトウェアを使って定型的な事務処理を自動化する。物理的なロボットによる製造や倉庫の自動化とは区別する。 中文解析：RPA使用软件自动执行录入、核对等规则明确的事务，与实体机器人自动化不同。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q62','exam-fe','SOA','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問62・改編】SOAを説明したものはどれか。','[{"id":"a","text":"既存組織や業務ルールを抜本的に見直し業務を再構築する手法"},{"id":"b","text":"企業資源を部門横断で統合管理する基幹業務システム"},{"id":"c","text":"委託者とサービス提供者が品質について合意した文書"},{"id":"d","text":"業務プロセスの構成要素とIT基盤をソフトウェア部品であるサービスとして提供するアーキテクチャ"}]','"d"','SOAは機能を再利用可能なサービスとして提供・連携する設計方針。ほかの選択肢はそれぞれBPR、ERP、SLAに対応する。 中文解析：SOA将业务功能作为可复用服务提供和组合；其余分别对应BPR、ERP和SLA。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q65','exam-fe','ベンダ選定','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問65・改編】RFIへの回答を得た各ベンダにRFPを提示した。公正な選定に向けて事前に実施すべきことはどれか。','[{"id":"a","text":"RFI評価の高いベンダに選定漏れ時の再提案救済措置を設ける"},{"id":"b","text":"現行システムを知るベンダを選びやすいよう別途高く評価する"},{"id":"c","text":"提案の評価基準と要求事項への重み付けを定め、選定手順を確立する"},{"id":"d","text":"全ベンダに内示書を発行して契約書作成を依頼する"}]','"c"','共通の評価基準、重み付け、手順を事前に定めることが公正で一貫した比較につながる。 中文解析：事先设定统一评价标准、权重和程序，有助于公平比较供应商提案。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q66','exam-fe','PPM','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問66・改編】プロダクトポートフォリオマネジメント（PPM）の「花形」を説明するものはどれか。','[{"id":"a","text":"市場成長率と市場占有率が共に高いが、成長に必要な投資もあり資金創出が大きいとは限らない"},{"id":"b","text":"市場成長率と市場占有率が共に低く、資金の創出と流出が少ない"},{"id":"c","text":"市場成長率は高いが市場占有率は低く、将来性は見込める"},{"id":"d","text":"市場成長率は低いが市場占有率は高く、企業の資金源となる"}]','"a"','PPMの花形は成長率・占有率がともに高い事業である。投資も必要なため資金創出と流出の両面を考える。 中文解析：明星业务的市场增长率和份额都高，但也需要投资，因此不一定带来大量净现金。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
