-- Source-checked strategy, financial and legal questions.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q67','exam-fe','プロダクトライフサイクル','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問67・改編】製品ライフサイクルの成熟期の特徴はどれか。','[{"id":"a","text":"市場が製品価値を理解し始め、売上と投資が増加する"},{"id":"b","text":"需要が大きく、差別化や市場細分化が進み、競争が激化してコスト削減が重要となる"},{"id":"c","text":"需要が減り撤退企業が現れ、代替市場への進出を考える"},{"id":"d","text":"需要は限定的で新規需要を開拓する"}]','"b"','成熟期は需要が広がり競争が激化する。差別化やコスト削減が重要となる。 中文解析：成熟期需求广泛、竞争激烈，产品差异化和降低成本变得重要。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q68','exam-fe','バランススコアカード','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問68・改編】バランススコアカードの内部ビジネスプロセスの視点における戦略目標と評価指標の組合せはどれか。','[{"id":"a","text":"持続的成長を目標とし、受注残を指標とする"},{"id":"b","text":"主要顧客との継続関係を目標とし、クレーム件数を指標とする"},{"id":"c","text":"製品開発力の向上を目標とし、研修受講時間を指標とする"},{"id":"d","text":"製造の生産性向上を目標とし、製造期間短縮日数を指標とする"}]','"d"','内部プロセスの視点では業務の効率や品質を測る。製造期間の短縮は製造工程の改善を表す。 中文解析：内部业务流程视角关注流程效率和质量，制造周期缩短属于该视角。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q70','exam-fe','かんばん方式','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問70・改編】かんばん方式の説明として適切なものはどれか。','[{"id":"a","text":"作業効率向上のため仕様が統一された部品を調達する"},{"id":"b","text":"効率よく部品を調達するため関連会社から調達する"},{"id":"c","text":"中間在庫を減らすため後工程で必要な部品だけを前工程から調達する"},{"id":"d","text":"品質向上のため複数の指定業者による競争入札で調達する"}]','"c"','かんばん方式は後工程が必要なものを必要な量だけ引き取ることで、仕掛在庫を抑える。 中文解析：看板方式由后工序按需要领取必要数量，减少在制库存。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q71','exam-fe','ブロックチェーン・マイニング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問71・改編】ブロックチェーンを利用した仮想通貨のマイニングの説明はどれか。','[{"id":"a","text":"取引の確認・記録に必要な計算作業に参加し、報酬として仮想通貨を得る"},{"id":"b","text":"仮想通貨を売買して値上がり益を得る"},{"id":"c","text":"個人や組織へ仮想通貨を送金する"},{"id":"d","text":"実店舗で仮想通貨を使って支払う"}]','"a"','問題のマイニングは取引の検証やブロック作成の計算に参加し報酬を得る仕組みを指す。すべての暗号資産が同じ方式ではない。 中文解析：本题的挖矿指参与交易验证和区块生成的计算并获得奖励；并非所有加密资产采用相同机制。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q72','exam-fe','利益最大化','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問72・改編】月間200時間を使い、同時並行なしで製品X・Y・Zを製造する。1個の利益はそれぞれ1,800円・2,500円・3,000円、製造時間は6分・10分・15分、需要上限は1,000個・900個・500個。実現できる最大利益は何円か。','[{"id":"a","text":"2,625,000"},{"id":"b","text":"3,000,000"},{"id":"c","text":"3,150,000"},{"id":"d","text":"3,300,000"}]','"d"','1分当たり利益はXが300円、Yが250円、Zが200円。Xを上限1,000個作ると6,000分・180万円、残り6,000分でYを600個作ると150万円。合計330万円。 中文解析：单位时间利润依次为X 300、Y 250、Z 200日元。先做X 1000个，再做Y 600个，合计330万日元。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q73','exam-fe','ロングテール','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問73・改編】ネット販売の売上全体に対し、個々には売れにくい商品の売上合計が無視できない割合を占めることを何というか。','[{"id":"a","text":"アフィリエイト"},{"id":"b","text":"オプトイン"},{"id":"c","text":"ドロップシッピング"},{"id":"d","text":"ロングテール"}]','"d"','ロングテールは販売数の少ない多種類の商品を合計すると大きな売上になる現象である。 中文解析：长尾指单品销量不高的大量商品累计起来占据不可忽视的销售额。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q74','exam-fe','ディープラーニング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問74・改編】車載機器の性能向上にディープラーニングを用いている例はどれか。','[{"id":"a","text":"加速度センサで衝突を検知してエアバッグを膨らませる"},{"id":"b","text":"大量の画像を取得・処理して歩行者と車の識別精度を高める"},{"id":"c","text":"アイドリングストップ機能を使って燃費を改善する"},{"id":"d","text":"携帯電話回線でソフトウェアを更新して地図を更新する"}]','"b"','大量画像から特徴を学び、歩行者や車の認識精度を高める利用が深層学習の例である。 中文解析：从大量图像学习特征以提高行人和车辆识别精度，是深度学习的应用。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q75','exam-fe','社内カンパニー制','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問75・改編】社内カンパニー制の説明はどれか。','[{"id":"a","text":"部門を切り離し別会社として独立させる"},{"id":"b","text":"合併や買収で他社の経営資源を取得する"},{"id":"c","text":"長期間の研究開発成果を経営戦略の基礎とする"},{"id":"d","text":"事業分野ごとに社内の仮想企業を設け、資源配分や意思決定を効率化する"}]','"d"','企業内の事業単位を独立性の高い仮想的な会社として扱う方式で、意思決定の迅速化などを図る。 中文解析：内部公司制将企业内各业务单元作为相对独立的虚拟公司经营，以加快决策。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q76','exam-fe','期待費用','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問76・改編】良品確率0.9、不良品確率0.1。1個あたりの良品・不良品の費用は案A=(0,1500円)、B=(40,1000円)、C=(80,500円)、D=(120,200円)。期待費用が最小の案はどれか。','[{"id":"a","text":"A"},{"id":"b","text":"B"},{"id":"c","text":"C"},{"id":"d","text":"D"}]','"c"','各案の期待費用はA=150円、B=136円、C=122円、D=128円。最小はC。 中文解析：分别计算0.9×良品费用＋0.1×不良品费用，A为150、B为136、C为122、D为128日元，C最低。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q78','exam-fe','貸借対照表','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問78・改編】一定時点の資産・負債・純資産を表示して財政状態を明らかにする財務諸表はどれか。','[{"id":"a","text":"株主資本等変動計算書"},{"id":"b","text":"キャッシュフロー計算書"},{"id":"c","text":"損益計算書"},{"id":"d","text":"貸借対照表"}]','"d"','貸借対照表は一定時点の資産、負債、純資産を示す。損益計算書は一定期間の収益と費用を示す。 中文解析：资产负债表反映特定时点的资产、负债和净资产；利润表反映一定期间的收入和费用。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q79','exam-fe','著作権','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問79・改編】著作権法で保護の対象となり得ないものはどれか。','[{"id":"a","text":"インターネット上で公開されたフリーソフトウェア"},{"id":"b","text":"ソフトウェアの操作マニュアル"},{"id":"c","text":"データベース"},{"id":"d","text":"プログラム言語や規約"}]','"d"','プログラム言語や規約そのものは著作権法上のプログラムの著作物の保護対象から除かれる。フリーソフトも著作権を放棄したとは限らない。 中文解析：程序语言和规则本身不属于程序著作物的保护对象；免费软件也不等于放弃版权。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q80','exam-fe','製造物責任法','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問80・改編】ソフトウェアやデータに瑕疵がある場合、製造物責任法の対象となるものはどれか。','[{"id":"a","text":"ROM化したソフトウェアを内蔵する組込み機器"},{"id":"b","text":"アプリケーションソフトウェアのパッケージ"},{"id":"c","text":"PCにインストールしたOS"},{"id":"d","text":"ネットワークからダウンロードしたデータ"}]','"a"','製造物責任法の対象は製造または加工された動産。ROMを組み込んだ機器は有体物であり、単独のソフトウェアやデータとは区別される。 中文解析：日本产品责任法的对象为制造或加工的动产。内置ROM的设备是有体物，应与单独的软件或数据区分。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
